// ---- content/b-word.js ----
// Школьная база · «Текстовые задачи: движение, работа, части» (1–6 класс) + олимпиадные задачи: система отсчёта, графики движения.
(function () {
  function fr(a, b) { return '<span class="fr"><span>' + a + '</span><span>' + b + '</span></span>'; }

  MM.addTopic({
    id: 'b-word',
    sec: 'base',
    title: 'Текстовые задачи: движение, работа, части',
    blurb: `Задачи на движение навстречу, вдогонку и по реке, на совместную работу, на части и на возраст. Умение перевести условие на язык чисел нужно в каждой олимпиадной задаче.`,

    lessons: [
      { id: 'wd-l1', title: 'Задачи на движение', mins: 12, html: `
<p>Главная формула: путь = скорость × время, <span class="m">s = vt</span>.</p>
<div class="box"><div class="box-h">Запомни</div><ul>
<li><b>Навстречу:</b> расстояние между движущимися сокращается со скоростью сближения <span class="m">v<sub>1</sub> + v<sub>2</sub></span>.</li>
<li><b>Вдогонку:</b> со скоростью <span class="m">v<sub>1</sub> − v<sub>2</sub></span>.</li>
<li><b>По реке:</b> по течению скорость <span class="m">v + u</span>, против течения <span class="m">v − u</span>, где u — скорость течения.</li>
</ul></div>
<div class="ex"><div class="ex-h">Пример</div>
<p>Из двух городов, расстояние между которыми 300 км, одновременно навстречу друг другу выехали машины со скоростями 70 и 80 км/ч. Через сколько часов они встретятся?</p>
<p><b>Решение.</b> Скорость сближения 150 км/ч, время <span class="m">300 : 150 = 2</span> ч.</p></div>
<div class="trick"><div class="trick-h">Олимпиадный приём</div>
<p>Средняя скорость — это весь путь, делённый на всё время, а не среднее арифметическое скоростей. Если полпути ехать со скоростью 30 км/ч, а полпути — 60 км/ч, средняя скорость 40 км/ч, а не 45.</p></div>` },

      { id: 'wd-l2', title: 'Задачи на работу, части и возраст', mins: 12, html: `
<h3>Работа</h3>
<p>Всю работу принимают за 1. Если человек делает её за 5 часов, то за час он делает <span class="m">${fr('1', '5')}</span> работы — это его производительность. Производительности работающих вместе <b>складываются</b>.</p>
<div class="ex"><div class="ex-h">Пример</div>
<p>Один насос откачивает воду за 4 часа, другой — за 12. За сколько часов они откачают её вместе?</p>
<p><b>Решение.</b> За час вместе <span class="m">${fr('1', '4')} + ${fr('1', '12')} = ${fr('4', '12')} = ${fr('1', '3')}</span>, поэтому вся работа — за 3 часа.</p></div>
<h3>Части</h3>
<p>Если одна величина в 3 раза больше другой, примем меньшую за 1 часть, тогда большая — 3 части, а вместе 4 части. Сумма известна — находим одну часть.</p>
<h3>Возраст</h3>
<p>Разница в возрасте двух людей не меняется со временем. Через t лет к возрасту каждого прибавляется t.</p>
<div class="trick"><div class="trick-h">Олимпиадный приём</div>
<p>Задачи «на части» и «на работу» решаются без уравнений, если правильно выбрать единицу: одна часть, вся работа, единица времени. Сначала найди единицу, потом всё остальное.</p></div>` }
    ],

    problems: [
      { id: 'wd-01', lvl: 1, r: 800, type: 'num', q: `Автомобиль ехал 3 часа со скоростью 70 км/ч. Сколько километров он проехал?`, a: ['210'],
        hints: [`s = vt.`], sol: `70 · 3 = 210 км.` },
      { id: 'wd-02', lvl: 1, r: 840, type: 'num', q: `Два пешехода одновременно вышли навстречу друг другу из пунктов, расстояние между которыми 18 км. Их скорости 4 км/ч и 5 км/ч. Через сколько часов они встретятся?`, a: ['2'],
        hints: [`Скорость сближения 9 км/ч.`], sol: `18 : 9 = 2 ч.` },
      { id: 'wd-03', lvl: 1, r: 880, type: 'num', q: `Скорость лодки в стоячей воде 12 км/ч, скорость течения 3 км/ч. За сколько часов лодка пройдёт 45 км против течения?`, a: ['5'],
        hints: [`Против течения скорость 12 − 3.`], sol: `45 : 9 = 5 ч.` },
      { id: 'wd-04', lvl: 1, r: 920, type: 'num', q: `Первая труба наполняет бассейн за 6 часов, вторая — за 3 часа. За сколько часов его наполнят обе трубы вместе?`, a: ['2'],
        hints: [`За час вместе: 1/6 + 1/3.`], sol: `${fr('1', '6')} + ${fr('1', '3')} = ${fr('1', '2')} бассейна в час, значит, за 2 часа.` },
      { id: 'wd-05', lvl: 1, r: 960, type: 'num', q: `В корзине яблок в 3 раза больше, чем груш, а всего 48 фруктов. Сколько в корзине груш?`, a: ['12'],
        hints: [`Груши — 1 часть, яблоки — 3 части.`], sol: `Всего 4 части, одна часть 48 : 4 = 12 — это груши.` },

      { id: 'wd-06', lvl: 2, r: 1050, type: 'num', q: `Велосипедист выехал на 2 часа позже пешехода по той же дороге и догнал его через 1 час после своего выезда. Скорость пешехода 5 км/ч. Найдите скорость велосипедиста (км/ч).`, a: ['15'],
        hints: [`К моменту встречи пешеход шёл 3 часа.`], sol: `Пешеход прошёл 5 · 3 = 15 км, велосипедист проехал те же 15 км за 1 час: 15 км/ч.` },
      { id: 'wd-07', lvl: 2, r: 1100, type: 'num', q: `Мастер выполняет работу за 12 дней, ученик — за 24 дня. За сколько дней они выполнят её вместе?`, a: ['8'],
        hints: [`За день вместе: 1/12 + 1/24.`], sol: `${fr('1', '12')} + ${fr('1', '24')} = ${fr('3', '24')} = ${fr('1', '8')} работы в день — 8 дней.` },
      { id: 'wd-08', lvl: 2, r: 1150, type: 'num', q: `Поезд длиной 300 м проходит мимо столба за 15 секунд. Найдите скорость поезда в км/ч.`, a: ['72'],
        hints: [`Мимо столба поезд проходит свою длину.`, `1 м/с = 3,6 км/ч.`], sol: `300 : 15 = 20 м/с = 72 км/ч.` },
      { id: 'wd-09', lvl: 2, r: 1200, type: 'num', q: `Сумма возрастов отца и сына 50 лет. Через 5 лет отец будет втрое старше сына. Сколько лет сыну сейчас?`, a: ['10'],
        hints: [`Через 5 лет сумма возрастов будет 60.`], sol: `Через 5 лет сумма 60 лет, и это 4 части (сын — 1, отец — 3): сыну будет 15, то есть сейчас 10.` },
      { id: 'wd-10', lvl: 2, r: 1250, type: 'num', q: `Первую половину пути автомобиль ехал со скоростью 60 км/ч, а вторую — со скоростью 40 км/ч. Найдите среднюю скорость на всём пути (км/ч).`, a: ['48'],
        hints: [`Возьми путь 240 км и посчитай всё время.`], sol: `Если путь 240 км: 120 : 60 = 2 ч и 120 : 40 = 3 ч, всего 5 ч. Средняя скорость 240 : 5 = 48 км/ч.` },

      { id: 'wd-11', lvl: 3, r: 1350, type: 'num', q: `Из A в B и из B в A одновременно вышли два поезда и встретились через 3 часа. После встречи первый шёл до B ещё 4 часа. Сколько часов после встречи шёл второй поезд до A?`, a: ['2.25', '9/4'],
        hints: [`До встречи второй прошёл за 3 ч столько, сколько первый проходит за 4 ч. Найди отношение скоростей.`], sol: `Путь второго до встречи первый проходит за 4 ч, а второй — за 3 ч, поэтому v<sub>1</sub> : v<sub>2</sub> = 3 : 4. Путь первого до встречи (3v<sub>1</sub>) второй пройдёт за ${fr('3v<sub>1</sub>', 'v<sub>2</sub>')} = 3 · ${fr('3', '4')} = 2,25 ч.` },
      { id: 'wd-12', lvl: 3, r: 1400, type: 'num', q: `Катер прошёл 48 км по течению реки за 3 часа, а обратно — за 4 часа. Найдите скорость течения (км/ч).`, a: ['2'],
        hints: [`Скорости по течению и против течения отличаются на удвоенную скорость течения.`], sol: `По течению 16 км/ч, против — 12 км/ч. Скорость течения (16 − 12) : 2 = 2 км/ч.` },
      { id: 'wd-13', lvl: 3, r: 1450, type: 'num', q: `Три трубы вместе наполняют бак за 2 часа. Первая одна наполняет его за 6 часов, вторая — за 5 часов. За сколько часов наполнит бак одна третья труба?`, a: ['7.5', '15/2'],
        hints: [`Производительность третьей: 1/2 − 1/6 − 1/5.`], sol: `${fr('1', '2')} − ${fr('1', '6')} − ${fr('1', '5')} = ${fr('15 − 5 − 6', '30')} = ${fr('2', '15')} бака в час, значит, 7,5 часа.` },
      { id: 'wd-14', lvl: 3, r: 1500, type: 'num', q: `Часы показывают ровно 3:00. Через сколько минут минутная стрелка впервые догонит часовую? Ответ запишите несократимой дробью.`, a: ['180/11'],
        hints: [`Минутная стрелка проходит 6° в минуту, часовая — 0,5°.`, `В 3:00 угол между ними 90°.`], sol: `Минутная догоняет часовую со скоростью 5,5° в минуту, разрыв 90°: ${fr('90', '5,5')} = ${fr('180', '11')} = 16${fr('4', '11')} минуты.` },
      { id: 'wd-15', lvl: 3, r: 1550, type: 'num', q: `Конфеты раздали поровну всем ученикам класса. Если бы учеников было на 5 больше, каждому досталось бы на 2 конфеты меньше, а если бы на 5 меньше — на 3 конфеты больше. Сколько всего конфет?`, a: ['300'],
        hints: [`Пусть учеников n, каждому по k конфет. Тогда (n + 5)(k − 2) = nk и (n − 5)(k + 3) = nk.`, `Раскрой скобки: 5k − 2n = 10 и 3n − 5k = 15.`], sol: `Из (n + 5)(k − 2) = nk получаем 5k − 2n = 10, из (n − 5)(k + 3) = nk — 3n − 5k = 15. Сложив, n = 25, тогда k = 12. Конфет 25 · 12 = 300.` }
    ]
  });

  MM.addDeep('b-word', {
    lessons: [
      { id: 'wd-l3', title: 'Система отсчёта и графики движения', mins: 14, html: `
<h3>Смени систему отсчёта</h3>
<p>Иногда удобно смотреть на движение «с точки зрения» одного из объектов. В системе отсчёта, связанной с водой, течения нет: и плот, и лодка, и потерянный предмет ведут себя так, будто река стоит.</p>
<div class="ex"><div class="ex-h">Пример</div>
<p>Лодка плывёт по реке, от неё отстаёт мяч. Через 15 минут лодка разворачивается. Через сколько минут она догонит мяч?</p>
<p><b>Решение.</b> В системе отсчёта воды мяч стоит на месте, а лодка уплывает и возвращается с одной и той же скоростью. Значит, обратный путь занимает те же 15 минут — скорость течения и скорость лодки не нужны.</p></div>
<h3>Два встречных движения подряд</h3>
<p>Если два объекта выезжают навстречу, встречаются, доезжают до концов и разворачиваются, то ко второй встрече вместе они проезжают <b>три</b> расстояния между пунктами, а к первой — одно. Значит, каждый к второй встрече проезжает втрое больше, чем к первой.</p>
<h3>Графики движения</h3>
<p>На графике «время — положение» каждое равномерное движение — отрезок прямой, встречи — точки пересечения отрезков, а наклон отрезка — скорость. Нарисовать график часто проще, чем составить уравнения: сразу видно, кто кого догоняет и когда.</p>
<div class="trick"><div class="trick-h">Олимпиадный приём</div>
<p>Если в задаче не хватает данных (неизвестна скорость лодки, длина пути), это подсказка: ответ от них не зависит. Выбери удобную систему отсчёта или конкретное значение — и всё упростится.</p></div>` }
    ],
    problems: [
      { id: 'wd-16', lvl: 4, r: 1700, type: 'num', q: `Пловец плывёт против течения реки. Проплывая под мостом, он потерял флягу, но заметил это через 20 минут, сразу развернулся и догнал флягу в 2 км ниже моста. Найдите скорость течения (км/ч).`, a: ['3'],
        hints: [`В системе отсчёта воды фляга неподвижна.`, `Сколько всего времени прошло от потери до встречи?`], sol: `Относительно воды фляга стоит, а пловец 20 минут уплывает и 20 минут возвращается. Значит, фляга плыла 40 минут и прошла 2 км: скорость течения 2 : ${fr('2', '3')} = 3 км/ч.` },
      { id: 'wd-17', lvl: 4, r: 1800, type: 'num', q: `Из A в B и из B в A одновременно выехали два велосипедиста. Они встретились в 12 км от A, доехали каждый до конца пути, сразу повернули обратно и встретились второй раз в 6 км от B. Найдите расстояние AB (км).`, a: ['30'],
        hints: [`Ко второй встрече они вместе проехали три расстояния AB.`, `Значит, первый проехал 3 · 12 = 36 км.`], sol: `К первой встрече вместе проехали AB, первый — 12 км. Ко второй встрече вместе 3AB, поэтому первый проехал 36 км: это AB + 6. Значит, AB = 30 км.` },
      { id: 'wd-18', lvl: 4, r: 1900, type: 'num', q: `Человек, идущий вверх по движущемуся эскалатору, поднимается за 40 секунд, а стоя на нём — за 60 секунд. За сколько секунд он поднимется пешком по неподвижному эскалатору?`, a: ['120'],
        hints: [`Скорости складываются: за секунду (человек + эскалатор) проходит 1/40 длины, эскалатор — 1/60.`], sol: `Скорость человека: ${fr('1', '40')} − ${fr('1', '60')} = ${fr('1', '120')} длины в секунду. Значит, 120 секунд.` },
      { id: 'wd-19', lvl: 5, r: 2000, type: 'num', q: `Колонна длиной 2 км движется со скоростью 4 км/ч. Из конца колонны в её начало и сразу обратно выехал гонец со скоростью 12 км/ч. Через сколько минут он вернётся в конец колонны?`, a: ['22.5'],
        hints: [`Относительно колонны гонец едет вперёд со скоростью 8 км/ч, а назад — 16 км/ч.`], sol: `Вперёд: ${fr('2', '12 − 4')} = 0,25 ч, назад: ${fr('2', '12 + 4')} = 0,125 ч. Всего 0,375 ч = 22,5 минуты.` },
      { id: 'wd-20', lvl: 5, r: 2100, type: 'num', q: `Две трубы вместе наполняют бассейн за 6 часов. Если первая проработает 4 часа, а потом вторая — 9 часов, бассейн тоже наполнится. За сколько часов наполнит бассейн одна первая труба?`, a: ['10'],
        hints: [`Пусть производительности a и b: a + b = 1/6, 4a + 9b = 1.`], sol: `4a + 9b = 4(a + b) + 5b = ${fr('4', '6')} + 5b = 1, откуда b = ${fr('1', '15')}, a = ${fr('1', '6')} − ${fr('1', '15')} = ${fr('1', '10')}. Первая труба — за 10 часов.` },
      { id: 'wd-21', lvl: 5, r: 2200, type: 'proof', q: `Один путник половину <b>времени</b> шёл со скоростью v<sub>1</sub>, а половину — со скоростью v<sub>2</sub>. Другой половину <b>пути</b> шёл со скоростью v<sub>1</sub>, а половину — со скоростью v<sub>2</sub> (v<sub>1</sub> ≠ v<sub>2</sub>). Докажите, что средняя скорость первого больше.`,
        hints: [`Средняя скорость первого — ${fr('v<sub>1</sub> + v<sub>2</sub>', '2')}. Посчитай среднюю скорость второго для пути 2s.`, `Сравни ${fr('v<sub>1</sub> + v<sub>2</sub>', '2')} и ${fr('2v<sub>1</sub>v<sub>2</sub>', 'v<sub>1</sub> + v<sub>2</sub>')}.`],
        sol: `Первый за время 2t проходит v<sub>1</sub>t + v<sub>2</sub>t, средняя скорость ${fr('v<sub>1</sub> + v<sub>2</sub>', '2')}. Второй тратит на путь 2s время ${fr('s', 'v<sub>1</sub>')} + ${fr('s', 'v<sub>2</sub>')}, его средняя скорость ${fr('2s', 's/v<sub>1</sub> + s/v<sub>2</sub>')} = ${fr('2v<sub>1</sub>v<sub>2</sub>', 'v<sub>1</sub> + v<sub>2</sub>')}. Неравенство ${fr('v<sub>1</sub> + v<sub>2</sub>', '2')} > ${fr('2v<sub>1</sub>v<sub>2</sub>', 'v<sub>1</sub> + v<sub>2</sub>')} равносильно (v<sub>1</sub> + v<sub>2</sub>)<sup>2</sup> > 4v<sub>1</sub>v<sub>2</sub>, то есть (v<sub>1</sub> − v<sub>2</sub>)<sup>2</sup> > 0, что верно при v<sub>1</sub> ≠ v<sub>2</sub>.`,
        rubric: [[2, `Средняя скорость первого`], [2, `Средняя скорость второго`], [3, `Сравнение сведено к (v<sub>1</sub> − v<sub>2</sub>)<sup>2</sup> > 0`]] }
    ]
  });
})();

